CREATE VIEW "ontology"."edition_view" AS (select "ontology"."node_version"."id", "ontology"."node_version"."version", "ontology"."node_version"."action", "tail"."isbn" as "isbn", "ontology"."node_version"."timestamp", "version_zero"."timestamp" as "created_at" from "ontology"."edition_version" inner join "ontology"."node_version" on (("ontology"."edition_version"."id" = "ontology"."node_version"."id") and ("ontology"."edition_version"."version" = "ontology"."node_version"."version")) inner join "ontology"."node" on "ontology"."edition_version"."id" = "ontology"."node"."id" cross join lateral (select "ontology"."manifestation_isbn"."isbn" as "isbn" from "ontology"."manifestation_version" left join "ontology"."manifestation_isbn" on (("ontology"."edition_version"."id" = "ontology"."manifestation_isbn"."id") and ("ontology"."edition_version"."version" = "ontology"."manifestation_isbn"."version")) where (("ontology"."edition_version"."id" = "ontology"."manifestation_version"."id") and ("ontology"."edition_version"."version" = "ontology"."manifestation_version"."version")) offset 0) "tail" inner join "ontology"."node_version" "version_zero" on (("ontology"."edition_version"."id" = "version_zero"."id") and ("version_zero"."version" = 0)) where not exists (select 1 from "ontology"."node_version" "newer" where (("newer"."id" = "ontology"."edition_version"."id") and ("newer"."version" > "ontology"."edition_version"."version"))));--> statement-breakpoint
CREATE VIEW "ontology"."organisation_view" AS (select "ontology"."node_version"."id", "ontology"."node_version"."version", "ontology"."node_version"."action", "ontology"."node_version"."timestamp", "version_zero"."timestamp" as "created_at" from "ontology"."organisation_version" inner join "ontology"."node_version" on (("ontology"."organisation_version"."id" = "ontology"."node_version"."id") and ("ontology"."organisation_version"."version" = "ontology"."node_version"."version")) inner join "ontology"."node" on "ontology"."organisation_version"."id" = "ontology"."node"."id" cross join lateral (select  from "ontology"."agent_version" where (("ontology"."organisation_version"."id" = "ontology"."agent_version"."id") and ("ontology"."organisation_version"."version" = "ontology"."agent_version"."version")) offset 0) "tail" inner join "ontology"."node_version" "version_zero" on (("ontology"."organisation_version"."id" = "version_zero"."id") and ("version_zero"."version" = 0)) where not exists (select 1 from "ontology"."node_version" "newer" where (("newer"."id" = "ontology"."organisation_version"."id") and ("newer"."version" > "ontology"."organisation_version"."version"))));--> statement-breakpoint
CREATE VIEW "ontology"."person_view" AS (select "ontology"."node_version"."id", "ontology"."node_version"."version", "ontology"."node_version"."action", "tail"."wikidata_id", "ontology"."node_version"."timestamp", "version_zero"."timestamp" as "created_at" from "ontology"."person_version" inner join "ontology"."node_version" on (("ontology"."person_version"."id" = "ontology"."node_version"."id") and ("ontology"."person_version"."version" = "ontology"."node_version"."version")) inner join "ontology"."node" on "ontology"."person_version"."id" = "ontology"."node"."id" cross join lateral (select "ontology"."person"."wikidata_id" from "ontology"."agent_version" inner join "ontology"."person" on "ontology"."person_version"."id" = "ontology"."person"."id" where (("ontology"."person_version"."id" = "ontology"."agent_version"."id") and ("ontology"."person_version"."version" = "ontology"."agent_version"."version")) offset 0) "tail" inner join "ontology"."node_version" "version_zero" on (("ontology"."person_version"."id" = "version_zero"."id") and ("version_zero"."version" = 0)) where not exists (select 1 from "ontology"."node_version" "newer" where (("newer"."id" = "ontology"."person_version"."id") and ("newer"."version" > "ontology"."person_version"."version"))));--> statement-breakpoint
CREATE VIEW "ontology"."essay_live_view" AS (select "ontology"."node_version"."id", "ontology"."node_version"."version", "head_row"."action", "ontology"."work_version"."title", "ontology"."node_version"."timestamp", "version_zero"."timestamp" as "created_at", "pointer"."at" as "live_at" from (select distinct on ("ontology"."live_pointer"."id") "id", "version" as "pointer_version", "at" from "ontology"."live_pointer" where "ontology"."live_pointer"."at" <= now() order by "ontology"."live_pointer"."id", "ontology"."live_pointer"."seq" desc) "pointer" inner join "ontology"."node_version" on (("pointer"."id" = "ontology"."node_version"."id") and ("pointer"."pointer_version" = "ontology"."node_version"."version")) inner join "ontology"."node" on "pointer"."id" = "ontology"."node"."id" inner join "ontology"."work_version" on (("pointer"."id" = "ontology"."work_version"."id") and ("pointer"."pointer_version" = "ontology"."work_version"."version")) cross join lateral (select  from "ontology"."essay_version" where (("pointer"."id" = "ontology"."essay_version"."id") and ("pointer"."pointer_version" = "ontology"."essay_version"."version")) offset 0) "tail" inner join "ontology"."node_version" "head_row" on "pointer"."id" = "head_row"."id" inner join "ontology"."node_version" "version_zero" on (("pointer"."id" = "version_zero"."id") and ("version_zero"."version" = 0)) where not exists (select 1 from "ontology"."node_version" "newer" where (("newer"."id" = "head_row"."id") and ("newer"."version" > "head_row"."version"))));--> statement-breakpoint
CREATE VIEW "ontology"."essay_locale_live_view" AS (select "ontology"."node_version"."id", "ontology"."node_version"."version", "head_row"."action", "ontology"."work_version"."title", "ontology"."essay_locale"."locale" as "locale", "ontology"."essay_locale"."abstract" as "abstract", "ontology"."node_version"."timestamp", "version_zero"."timestamp" as "created_at", "pointer"."at" as "live_at" from (select distinct on ("ontology"."live_pointer"."id") "id", "version" as "pointer_version", "at" from "ontology"."live_pointer" where "ontology"."live_pointer"."at" <= now() order by "ontology"."live_pointer"."id", "ontology"."live_pointer"."seq" desc) "pointer" inner join "ontology"."node_version" on (("pointer"."id" = "ontology"."node_version"."id") and ("pointer"."pointer_version" = "ontology"."node_version"."version")) inner join "ontology"."node" on "pointer"."id" = "ontology"."node"."id" inner join "ontology"."work_version" on (("pointer"."id" = "ontology"."work_version"."id") and ("pointer"."pointer_version" = "ontology"."work_version"."version")) cross join lateral (select  from "ontology"."essay_version" where (("pointer"."id" = "ontology"."essay_version"."id") and ("pointer"."pointer_version" = "ontology"."essay_version"."version")) offset 0) "tail" left join "ontology"."essay_locale" on (("pointer"."id" = "ontology"."essay_locale"."id") and ("pointer"."pointer_version" = "ontology"."essay_locale"."version")) inner join "ontology"."node_version" "head_row" on "pointer"."id" = "head_row"."id" inner join "ontology"."node_version" "version_zero" on (("pointer"."id" = "version_zero"."id") and ("version_zero"."version" = 0)) where not exists (select 1 from "ontology"."node_version" "newer" where (("newer"."id" = "head_row"."id") and ("newer"."version" > "head_row"."version"))));--> statement-breakpoint
CREATE VIEW "ontology"."supplement_view" AS (select "ontology"."node_version"."id", "ontology"."node_version"."version", "ontology"."node_version"."action", "ontology"."collection_version"."name", "tail"."code", "ontology"."series_version"."cadence", "ontology"."supplement_version"."label", "ontology"."node_version"."timestamp", "version_zero"."timestamp" as "created_at" from "ontology"."supplement_version" inner join "ontology"."node_version" on (("ontology"."supplement_version"."id" = "ontology"."node_version"."id") and ("ontology"."supplement_version"."version" = "ontology"."node_version"."version")) inner join "ontology"."node" on "ontology"."supplement_version"."id" = "ontology"."node"."id" inner join "ontology"."collection_version" on (("ontology"."supplement_version"."id" = "ontology"."collection_version"."id") and ("ontology"."supplement_version"."version" = "ontology"."collection_version"."version")) inner join "ontology"."series_version" on (("ontology"."supplement_version"."id" = "ontology"."series_version"."id") and ("ontology"."supplement_version"."version" = "ontology"."series_version"."version")) cross join lateral (select "code" from "ontology"."series" where "ontology"."supplement_version"."id" = "ontology"."series"."id" offset 0) "tail" inner join "ontology"."node_version" "version_zero" on (("ontology"."supplement_version"."id" = "version_zero"."id") and ("version_zero"."version" = 0)) where not exists (select 1 from "ontology"."node_version" "newer" where (("newer"."id" = "ontology"."supplement_version"."id") and ("newer"."version" > "ontology"."supplement_version"."version"))));--> statement-breakpoint
